<script setup>
import {ref,watch} from 'vue';import {useRoute,RouterLink} from 'vue-router';import {api} from '../lib/api';import {money,display,date,num} from '../lib/format';import PageCard from '../components/PageCard.vue';
const data=ref(null),query=ref(''),year=ref(''),kind=ref(''),rubro=ref(''),page=ref(1),error=ref('');
async function load(){try{data.value=await api.get('/ventas/documentos?'+new URLSearchParams({q:query.value,anio:year.value,tipo:kind.value,rubro:rubro.value,page:page.value}))}catch(e){error.value=e.message}}
watch([year,kind,rubro,page],load,{immediate:true});
</script>
<template><div class="page-heading"><div class="page-heading__titles"><h1 class="page-title display">Libro de ventas</h1><p class="page-description">Facturas, facturas exentas y notas de crédito registradas</p></div><div class="page-actions"><RouterLink to="/ventas" class="btn">← Volver</RouterLink><RouterLink to="/ventas/documentos/nuevo" class="btn btn-primary">+ Registrar documento</RouterLink></div></div><p v-if="error" class="notice bad">{{error}}</p><PageCard title="Filtros"><form class="form-grid" @submit.prevent="page=1;load()"><div class="field"><label>Buscar</label><input v-model="query" placeholder="Cliente, RUT, N° u obra"/></div><div class="field"><label>Año</label><input v-model="year" type="number" placeholder="Todos"/></div><div class="field"><label>Tipo</label><select v-model="kind"><option value="">Todos</option><option v-for="[v,label] in data?.kinds||[]" :key="v" :value="v">{{label}}</option></select></div><div class="field"><label>Rubro</label><select v-model="rubro"><option value="">Todos</option><option v-for="[v,label] in data?.rubros||[]" :key="v" :value="v">{{label}}</option></select></div><button class="btn btn-primary">Buscar</button></form></PageCard>
<PageCard :title="`Documentos · ${data?.count||0}`"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Fecha</th><th>Documento</th><th>N°</th><th>Cliente</th><th>RUT</th><th>Afecto $</th><th>UF</th><th></th></tr></thead><tbody><tr v-for="doc in data?.results||[]" :key="doc.id"><td>{{date(doc.fecha)}}</td><td>{{doc.tipo_documento}}</td><td>{{doc.numero}}</td><td>{{doc.razon_social}}</td><td>{{doc.rut_cliente}}</td><td>{{num(doc.afecto)}}</td><td>{{money(doc.afecto_uf)}}</td><td><RouterLink :to="'/ventas/documentos/'+doc.id" class="btn btn-sm">Editar</RouterLink></td></tr><tr v-if="!data?.results?.length"><td colspan="8">No hay documentos en este filtro.</td></tr></tbody></table></div><div class="page-actions" style="margin-top:14px"><button class="btn btn-sm" :disabled="page<=1" @click="page--">← Anterior</button><span>Página {{data?.page||1}} de {{data?.pages||1}}</span><button class="btn btn-sm" :disabled="page>=data?.pages" @click="page++">Siguiente →</button></div></PageCard></template>
